from __future__ import annotations

import json
from pathlib import Path

PATH = Path('src/i18n/locales/de/racePreparation.json')

def set_path(data, path, value):
    node = data
    parts = path.split('.')
    for part in parts[:-1]:
        node = node[part]
    node[parts[-1]] = value

